-- Migration 001: single-owner encrypted vault, applied in one transaction.
CREATE TABLE IF NOT EXISTS schema_migrations(version INTEGER PRIMARY KEY);
CREATE TABLE IF NOT EXISTS metadata(name TEXT PRIMARY KEY, value BLOB NOT NULL);
CREATE TABLE IF NOT EXISTS owner(id INTEGER PRIMARY KEY CHECK(id=1), password_hash TEXT NOT NULL, github_id TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS settings(id INTEGER PRIMARY KEY CHECK(id=1), revision INTEGER NOT NULL, data TEXT NOT NULL, github_secret BLOB, github_secret_revision INTEGER NOT NULL DEFAULT 0, resend_key BLOB, resend_key_revision INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS workspaces(id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS keys(id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id), path TEXT NOT NULL, active_version_id TEXT, disabled INTEGER NOT NULL DEFAULT 0, deleted INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL, UNIQUE(workspace_id,path), UNIQUE(workspace_id,id));
CREATE TABLE IF NOT EXISTS key_versions(id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL, key_id TEXT NOT NULL, number INTEGER NOT NULL, encrypted BLOB NOT NULL, expires_at INTEGER, expiry_revision INTEGER NOT NULL DEFAULT 1, created_at INTEGER NOT NULL, UNIQUE(key_id,number), UNIQUE(key_id,id), FOREIGN KEY(workspace_id,key_id) REFERENCES keys(workspace_id,id));
CREATE TRIGGER IF NOT EXISTS immutable_key_version BEFORE UPDATE OF id,workspace_id,key_id,number,encrypted,created_at ON key_versions BEGIN SELECT RAISE(ABORT,'immutable key version'); END;
CREATE TRIGGER IF NOT EXISTS active_version_scope BEFORE UPDATE OF active_version_id ON keys WHEN NEW.active_version_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM key_versions WHERE id=NEW.active_version_id AND key_id=NEW.id) BEGIN SELECT RAISE(ABORT,'invalid active version'); END;
CREATE TABLE IF NOT EXISTS tags(id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id), name TEXT NOT NULL, UNIQUE(workspace_id,name), UNIQUE(workspace_id,id));
CREATE TABLE IF NOT EXISTS key_tags(workspace_id TEXT NOT NULL, key_id TEXT NOT NULL, tag_id TEXT NOT NULL, PRIMARY KEY(key_id,tag_id), FOREIGN KEY(workspace_id,key_id) REFERENCES keys(workspace_id,id), FOREIGN KEY(workspace_id,tag_id) REFERENCES tags(workspace_id,id));
CREATE TABLE IF NOT EXISTS policies(id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id), name TEXT NOT NULL, active_version INTEGER NOT NULL, disabled INTEGER NOT NULL DEFAULT 0, UNIQUE(workspace_id,name), UNIQUE(workspace_id,id));
CREATE TABLE IF NOT EXISTS policy_versions(policy_id TEXT NOT NULL REFERENCES policies(id), version INTEGER NOT NULL, spec TEXT NOT NULL, created_at INTEGER NOT NULL, PRIMARY KEY(policy_id,version));
CREATE TRIGGER IF NOT EXISTS immutable_policy_version BEFORE UPDATE ON policy_versions BEGIN SELECT RAISE(ABORT,'immutable policy version'); END;
CREATE TABLE IF NOT EXISTS policy_key_targets(workspace_id TEXT NOT NULL, policy_id TEXT NOT NULL, version INTEGER NOT NULL, key_id TEXT NOT NULL, PRIMARY KEY(policy_id,version,key_id), FOREIGN KEY(policy_id,version) REFERENCES policy_versions(policy_id,version), FOREIGN KEY(workspace_id,policy_id) REFERENCES policies(workspace_id,id), FOREIGN KEY(workspace_id,key_id) REFERENCES keys(workspace_id,id));
CREATE TABLE IF NOT EXISTS policy_tag_targets(workspace_id TEXT NOT NULL, policy_id TEXT NOT NULL, version INTEGER NOT NULL, tag_id TEXT NOT NULL, PRIMARY KEY(policy_id,version,tag_id), FOREIGN KEY(policy_id,version) REFERENCES policy_versions(policy_id,version), FOREIGN KEY(workspace_id,policy_id) REFERENCES policies(workspace_id,id), FOREIGN KEY(workspace_id,tag_id) REFERENCES tags(workspace_id,id));
CREATE TABLE IF NOT EXISTS sessions(hash TEXT PRIMARY KEY, csrf TEXT NOT NULL, expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS admin_tokens(id TEXT PRIMARY KEY, name TEXT NOT NULL, hash TEXT UNIQUE NOT NULL, created_at INTEGER NOT NULL, expires_at INTEGER NOT NULL, revoked INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS oauth_flows(hash TEXT PRIMARY KEY, browser_hash TEXT NOT NULL, verifier TEXT NOT NULL, settings_revision INTEGER NOT NULL, expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS audit_events(id TEXT PRIMARY KEY, created_at INTEGER NOT NULL, request_id TEXT NOT NULL, actor TEXT NOT NULL, event TEXT NOT NULL, decision TEXT NOT NULL, workspace_id TEXT NOT NULL DEFAULT '', details TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS audit_time ON audit_events(created_at);
CREATE TABLE IF NOT EXISTS oidc_requests(jti_hash TEXT PRIMARY KEY, request_hash TEXT NOT NULL, versions TEXT NOT NULL, first_at INTEGER NOT NULL, attempts INTEGER NOT NULL, expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS idempotency(key TEXT PRIMARY KEY, request_hash TEXT NOT NULL, response TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS notifications(id TEXT PRIMARY KEY, version_id TEXT NOT NULL REFERENCES key_versions(id), expiry_revision INTEGER NOT NULL, threshold INTEGER NOT NULL, settings_revision INTEGER NOT NULL, status TEXT NOT NULL, payload TEXT NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, first_attempt_at INTEGER, next_attempt_at INTEGER NOT NULL, created_at INTEGER NOT NULL, sent_at INTEGER, provider_id TEXT NOT NULL DEFAULT '', last_error TEXT NOT NULL DEFAULT '', UNIQUE(version_id,expiry_revision,threshold));
CREATE INDEX IF NOT EXISTS notification_due ON notifications(status,next_attempt_at);
INSERT OR IGNORE INTO schema_migrations(version) VALUES(1);
